    bind(tracker,'[data-drop-status]','dragover',(_,e)=>e.preventDefault());bind(tracker,'[data-drop-status]','drop',(n,e)=>{e.preventDefault();const i=issues().find(i=>i.key===e.dataTransfer.getData('text/x-suite-issue'));if(i){i.history.push(`Статус: ${i.status} → ${n.dataset.dropStatus}`);i.status=n.dataset.dropStatus;renderTasks();}});
    if($('#stoPlanSprint',tracker))$('#stoPlanSprint',tracker).onclick=()=>inputDialog('Планирование спринта',`${field('Название',input('name','Спринт '+(29+sprints().size-1)))}${field('Цель',textarea('goal'))}<div class="sto-note">Выберите задачи бэклога для следующего спринта.</div>${issues().filter(i=>i.sprint==='Бэклог'&&!i.archived).map(i=>`<label class="sto-row"><input type="checkbox" name="issue" value="${i.key}"> ${i.key} · ${esc(i.title)}</label>`).join('')}`,'Создать план',data=>{const name=String(data.get('name')||'').trim();if(!name)return false;if(sprints().has(name)){notice('Спринт с таким названием уже существует');return false;}sprints().set(name,{name,goal:String(data.get('goal')||'').trim(),closed:false});data.getAll('issue').forEach(key=>{const i=issues().find(i=>i.key===key);i.sprint=name;i.history.push('Добавлена в '+i.sprint);});activeSprint=name;taskSprint='Все спринты';taskView='Спринт';renderTasks();notice('План спринта сохранён в макете');});
