  function resourceYaml(r,t){return `apiVersion: ${['Deployment','StatefulSet','DaemonSet'].includes(r.kind)?'apps/v1':'v1'}\nkind: ${r.kind}\nmetadata:\n  name: ${r.name}\n  namespace: ${t.namespace}\n  resourceVersion: "${r.version}"\nspec:\n  replicas: ${r.replicas}\n  # Демонстрационная структура; реальный YAML приходит из API.\n`;}
